\emph{Sensors: 
} \\
\For {\KwEach \emph{sensor $\ensuremath{v}$ in parallel}}{
  Sample $r_{\ensuremath{v}}$ uniformly at random from $[0,1]$.\\
  \If {$(r_{\ensuremath{v}} \ge 1 - \alpha \cdot \rho(w_{\ensuremath{v}}(t), Z_{\ensuremath{v}}(t))$}{
    Send $\tuple{r_{\ensuremath{v}}, w_{\ensuremath{v}}(t)}$ to the server.\\
    Receive message $\tuple{Z, w}$ from server.\\
    $Z_{\ensuremath{v}}(t+1) \gets Z$; $w_{\ensuremath{v}}(t+1) \gets w$. \\
  }\lElse{

     $Z_{\ensuremath{v}}(t+1) \gets Z_{\ensuremath{v}}(t)$; $w_{\ensuremath{v}}(t+1) \gets w_{\ensuremath{v}}(t)$.\\
  }
}
\emph{Server:}\\
 Receive messages from a set $S$ of sensors. \\
 \lIf{$S = \emptyset$}{Select nothing and wait for next round.}
 \lElse{
     \For {\KwEach \emph{sensor} $\ensuremath{v} \in S$}{
       $Y_{\ensuremath{v}} \gets \min \set{x : \prob{X \le x} \ge r_{\ensuremath{v}}}$, 
       where $X \sim \Poisson{\alpha \cdot \rho(w_{\ensuremath{v}}(t),Z(t))}$.\\



       Select $\ensuremath{v}$ with probability
$Y_{\ensuremath{v}}/\sum_{\ensuremath{v}' \in S} Y_{\ensuremath{v}'}$.\\
       Observe the payoff $\ensuremath{\pi}$ for the selected
       sensor $\ensuremath{v}^*$;  
       $w_{\ensuremath{v}^*}(t+1) \gets w_{\ensuremath{v}^*}(t) \cdot \exp
       \set{\eta \ensuremath{\pi} /  \rho(w_{\ensuremath{v}^*}(t),Z(t))}$;
       $Z(t+1) \gets Z(t) + w_{\ensuremath{v}^*}(t+1) -  w_{\ensuremath{v}^*}(t)$\;
       \lFor{ \KwEach $\ensuremath{v} \in S \setminus \ensuremath{v}^*$}{
          $w_{\ensuremath{v}}(t+1) \gets w_{\ensuremath{v}}(t)$\;
       }



       \lFor{ \KwEach $\ensuremath{v} \!\in\! S$}{
         Send $\tuple{Z(t\!+\!1), w_{\ensuremath{v}}(t\!+\!1)}$ to $\ensuremath{v}$.\\
    }
  }
}
